schema:
CREATE TABLE "projects" ("project_id" INTEGER PRIMARY KEY);

CREATE TABLE "project_phases" ("project_id" INTEGER UNIQUE, "phase_no" INTEGER UNIQUE, PRIMARY KEY ("project_id", "phase_no"), FOREIGN KEY ("project_id") REFERENCES "projects" ("project_id"));

CREATE TABLE "phase_tasks" ("project_id" INTEGER UNIQUE, "phase_no" INTEGER UNIQUE, "task_no" INTEGER UNIQUE, PRIMARY KEY ("project_id", "phase_no", "task_no"), FOREIGN KEY ("project_id") REFERENCES "project_phases" ("project_id"), FOREIGN KEY ("phase_no") REFERENCES "project_phases" ("phase_no"));

CREATE TABLE "task_assignments" ("project_id" INTEGER, "phase_no" INTEGER, "task_no" INTEGER, "worker_id" INTEGER, PRIMARY KEY ("project_id", "phase_no", "task_no", "worker_id"), FOREIGN KEY ("project_id") REFERENCES "phase_tasks" ("project_id"), FOREIGN KEY ("phase_no") REFERENCES "phase_tasks" ("phase_no"), FOREIGN KEY ("task_no") REFERENCES "phase_tasks" ("task_no"));
